{
  "name": "汐见町",
  "description": "汐见町是一座沿海小镇，旧车站早已停运，锈蚀的铁轨旁长满野草。车站前的小街铺着石板，两旁是安静的住宅、一家老咖啡馆和一座公共花园。海风常年吹拂，午后能听见远处潮声，住在这里的人们彼此熟识，日子缓慢而安稳。",
  "locations": [
    {
      "name": "旧车站月台",
      "description": "废弃的站台，铁轨被野草淹没，候车长椅上总有人看海。"
    },
    {
      "name": "车站前小街",
      "description": "石板铺就的短街，连接车站、咖啡馆和住宅区，是小镇日常动线。"
    },
    {
      "name": "潮汐咖啡馆",
      "description": "小街中段的老咖啡馆，木质吧台，老板熟悉每位熟客的口味。"
    },
    {
      "name": "汐见花园",
      "description": "街尾的公共花园，种满耐盐的月季与薰衣草，设有长椅和喷泉。"
    },
    {
      "name": "临海住宅区",
      "description": "小街旁安静的住宅小巷，矮墙小院，住着几户长住人家。"
    },
    {
      "name": "海堤步道",
      "description": "沿防波堤延伸的步道，清晨有人慢跑，傍晚有人散步看落日。"
    },
    {
      "name": "小镇杂货铺",
      "description": "街角的小铺子，卖日用品和本地海产干货，也是街坊交换消息的地方。"
    }
  ]
}

