{
  "name": "直路草原",
  "description": "一片开阔的草原缓缓铺展到天边，中央一条笔直的碎石路纵贯南北，从草浪里切出一道浅色的线。路边孤零零立着一间带大院子的咖啡馆，木栅栏围出院落，院子外再无别的建筑，也看不到围墙和走廊。住在这里的人们散居在草原各处，日子安静、缓慢，彼此之间隔着风与草的距离。",
  "locations": [
    {
      "name": "直路",
      "description": "一条笔直穿过草地的碎石路，南北延伸，是来往者唯一的路径。"
    },
    {
      "name": "大院子咖啡馆",
      "description": "路边唯一的建筑，带一个开阔的院子，人们在这里喝咖啡、闲坐、交换近况。"
    },
    {
      "name": "北端草坡",
      "description": "直路北端微微隆起的草坡，风大，适合远望整条路和咖啡馆的屋顶。"
    },
    {
      "name": "南端水洼",
      "description": "直路南端一片常年积水的浅洼，周围草长得高，傍晚常有鸟群落下。"
    },
    {
      "name": "东侧牧棚",
      "description": "草地东边一间没有墙的简易牧棚，只搭了顶，供放牧者歇脚和堆放草料。"
    },
    {
      "name": "西侧旧风车",
      "description": "草地西边一架不再转动的旧风车，铁架锈了，是孩子们爱爬的地方。"
    },
    {
      "name": "散居帐篷",
      "description": "草原上零散分布的几个居住帐篷，彼此隔得很远，没有围墙也没有走廊。"
    }
  ]
}

{
  "name": "石灯镇",
  "description": "石灯镇是一座被一条笔直鹅卵石路贯穿南北的宁静小镇，路的两旁是低矮的老屋与零星店铺。小镇气候温和，四季分明，居民们彼此熟识，生活节奏缓慢而踏实。这里的人们习惯在傍晚聚集到北端的小广场，有人在咖啡馆里消磨午后，有人守着住宅二楼的窗台看街景。镇上流传着关于广场中央那盏石灯来历的模糊传说，至今无人能说清它的真正年代。",
  "locations": [
    {
      "name": "鹅卵石路",
      "description": "一条笔直的鹅卵石路从南到北穿过小镇，是居民往来的主要通道。"
    },
    {
      "name": "旧时光咖啡馆",
      "description": "位于鹅卵石路旁的小咖啡馆，几张木桌、一墙旧书，是闲聊和独处的好去处。"
    },
    {
      "name": "两层住宅",
      "description": "紧邻咖啡馆的一栋两层老住宅，一楼是客厅与厨房，二楼住着房东或租客。"
    },
    {
      "name": "石灯广场",
      "description": "鹅卵石路北端的小广场，铺着同样的石块，白天有人摆摊，夜晚常有居民散步。"
    },
    {
      "name": "中央石灯",
      "description": "广场正中央立着一盏古老石灯，灯身刻有模糊纹路，入夜后仍有人为它点灯。"
    },
    {
      "name": "南口杂货铺",
      "description": "鹅卵石路南端的小铺子，卖日用杂货和当地特产，也是消息集散地。"
    },
    {
      "name": "镇西小教堂",
      "description": "一座简朴的老教堂，周末有礼拜，平时安静，偶尔举办社区活动。"
    },
    {
      "name": "东侧河岸步道",
      "description": "沿镇东小河铺设的步道，可以钓鱼、慢跑或坐在长椅上发呆。"
    }
  ]
}

{
  "name": "广场街",
  "description": "广场街紧邻小镇中央的钟楼广场，是镇上最热闹又最安静的一条街。石板路两侧排着老梧桐，风一吹就有叶子落在咖啡馆门前。街上住着几户老邻居，也租给过路的年轻人，谁家的灯亮着，谁家今天没拉开窗帘，街坊心里都有数。咖啡馆是这条街的心脏，人们在这里交换消息、消磨下午，有时也把心事说给不该听的人。",
  "locations": [
    {
      "name": "广场街",
      "description": "一条挨着广场的石板小街，两边是店铺和住家，街口正对钟楼。"
    },
    {
      "name": "钟楼广场",
      "description": "小镇中心的卵石广场，钟楼每小时敲一次，人们在这里等车、闲聊、喂鸽子。"
    },
    {
      "name": "梧桐咖啡馆",
      "description": "广场街上唯一的咖啡馆，木门铜铃，靠窗的位置能看到整条街和广场一角。"
    },
    {
      "name": "街角杂货铺",
      "description": "街尾的小铺子，卖日用杂货和当天面包，老板认识街上的每一个人。"
    },
    {
      "name": "沿河小径",
      "description": "广场街尽头拐向河边的小路，晨跑和晚饭后散步的人都走这里。"
    },
    {
      "name": "旧公寓楼",
